syntax:
Resource-owning class with constructor acquiring resource and destructor releasing resource

class Resource {
public:
    Resource(); // acquire resource
    ~Resource(); // release resource
};

code_example:
#include <fstream>
class FileCloser {
public:
    explicit FileCloser(std::ofstream& file) : file_(file) {}
    ~FileCloser() {
        if (file_.is_open()) {
            file_.close();
        }
    }
private:
    std::ofstream& file_;
};
int main() {
    std::ofstream file("example.txt");
    if (!file) {
        return 1; // handle error
    }
    FileCloser closer(file); // resource managed via RAII
    file << "Hello, RAII!"; // perform file operations
    // file will be closed automatically when 'closer' goes out of scope
    return 0;
}
